flows = {'North': 5200, 'East': 3800, 'South': 2900}
# Option 1: single hub at Aldgate
dist1 = {'North': 210, 'East': 330, 'South': 470}
cost1 = sum(flows[r] * dist1[r] for r in flows) * 0.012 + 41000
# Option 2: two hubs, Aldgate (North+East) and Breck (South)
dist2 = {'North': 190, 'East': 300, 'South': 120}
cost2 = sum(flows[r] * dist2[r] for r in flows) * 0.012 + 2 * 26000
print(f"Option 1 total daily cost: ${cost1:,.2f}")
print(f"Option 2 total daily cost: ${cost2:,.2f}")
print(f"Difference: ${abs(cost1-cost2):,.2f} in favour of option {1 if cost1<cost2 else 2}")
